# -*- coding: utf-8 -*-
# Тексты сообщений 3051-3075.
T = {
3051: {"t": "Колеги-викладачі, потрібно визначитися з датою засідання методичної комісії щодо оновлення освітньої програми. Пропонуємо два варіанти: у середу або у четвер наступного тижня, в обох випадках об 11:00 в аудиторії 418 (корпус №5). Будь ласка, позначте зручний день у формі опитування під цим повідомленням до п'ятниці. Остаточне рішення повідомимо після підсумків голосування. Нагадуємо, що до засідання кожна кафедра має підготувати пропозиції щодо переліку вибіркових дисциплін.",
       "ev": []},
3052: {"t": "Кафедра програмної інженерії проводить семінар «Великі мовні моделі в освіті». Зустрічаємося післязавтра об 11:00 в аудиторії 318 (корпус №5). Обговоримо, як мовні моделі змінюють навчання програмування: де вони справді допомагають, а де заважають опанувати базові навички, як оцінювати роботи, написані з допомогою ШІ, і що вже зафіксовано в політиці академічної доброчесності університету. Доповідачі — викладачі кафедри, які протягом семестру тестували такі інструменти на своїх курсах. Після доповідей — відкрита дискусія.",
       "ev": [("Семінар «Великі мовні моделі в освіті»", [["мовн"]])]},
3053: {"t": "Компанія CloudPeak запрошує магістрантів на лекцію «Криптографія на еліптичних кривих у хмарній інфраструктурі». Лекція відбудеться наступної п'ятниці об 11.00 в офісі компанії за адресою вул. Каштанова, 21. Архітектор із безпеки пояснить, як працюють протоколи ECDH та ECDSA, чому для них важлива якість генератора випадкових чисел і як компанія керує ключами в тисячах сервісів. Кількість місць обмежена пропускною системою офісу, тому реєстрація обов'язкова: https://reg.example.ua/signup-2852.",
       "ev": [("Лекція «Криптографія на еліптичних кривих у хмарній інфраструктурі»", [["еліптичн"]])]},
3054: {"t": "Студенти-журналісти Степового гуманітарного університету запрошують на свій щорічний медіафестиваль, який відбудеться 12 грудня на базі їхнього університету. Відкриття фестивалю — о 12:40 в ауд. 420, корпус 4 їхнього навчального містечка. Наш факультет не є партнером заходу, тому ми лише ділимося інформацією для тих, кого цікавить журналістика даних. Подробиці та програму шукайте на сторінці фестивалю в соцмережах університету-господаря.",
       "ev": []},
3055: {"t": "Новини сусідів: Прибузький аграрний університет 10 вересня відкриває у себе лабораторію точного землеробства з дронами та супутниковим моніторингом. Урочисте відкриття запланували на 16:20 в аудиторії 212 (корпус №1) їхнього університету, туди запрошені представники агрокомпаній і місцевої влади. Для нас це хороший приклад того, як ІТ приходять в аграрну галузь, тож радимо стежити за їхніми дослідженнями. Можливо, згодом з'являться й спільні студентські проєкти.",
       "ev": []},
3056: {"t": "Кафедра програмної інженерії запрошує студентів 2 курсу на майстер-клас з Figma для розробників. Через обмежену кількість комп'ютерів проведемо його двічі з однаковою програмою: 14 грудня та 21 грудня, обидва рази о 9:30 в ауд. 422, корпус 1. Оберіть одну зручну дату. Навчимося читати макети дизайнерів, експортувати ресурси, працювати з автолейаутом і передавати стилі в код без ручного копіювання кольорів. Бажано заздалегідь створити безкоштовний акаунт у Figma.",
       "ev": [("Майстер-клас з Figma для розробників", [["figma"]]),
              ("Майстер-клас з Figma для розробників", [["figma"]])]},
3057: {"t": "Шановні учасники! Воркшоп з розробки чат-ботів для Telegram, який мав відбутися 31 жовтня о 14:00 в аудиторії 524 (корпус №4), не відбудеться: компанія-партнер не змогла забезпечити приїзд ментора. Ми шукаємо можливість провести заняття пізніше, але конкретної дати поки немає. Реєстрацію не анулюємо — усіх, хто записався, повідомимо, щойно з'явиться нова дата. Вибачте за незручності та дякуємо за терпіння.",
       "ev": []},
3058: {"t": "Кафедра прикладної математики запрошує студентів старших курсів на практикум з Linux для початківців, який пройде у суботу, 5 грудня, в ауд. 111 корпусу 3. Розберемо роботу в терміналі, права доступу до файлів, керування процесами, встановлення пакетів і написання простих bash-скриптів для автоматизації рутинних задач. Кожен учасник працюватиме на власній віртуальній машині, тому ноутбук обов'язковий. Точний час початку узгодимо в чаті учасників після формування групи.",
       "ev": [("Практикум з Linux для початківців", [["linux"]])]},
3059: {"t": "Хтось записував лабораторну з баз даних, яку ми писали 26 жовтня о 16:20 в аудиторії 507 (корпус №2)? Викладач тоді продиктував умову додаткового завдання про тригери, а я встиг записати тільки половину. Скиньте, будь ласка, фото умови або перешліть файл, якщо хтось робив нотатки на ноутбуці. Здавати треба вже скоро, а в Moodle цього завдання чомусь немає. Дякую заздалегідь!",
       "ev": []},
3060: {"t": "Відділ міжнародних зв'язків запрошує студентів спеціальності 121 долучитися до міжнародної науково-практичної конференції «Інтелектуальні системи та технології», яка проходитиме онлайн 22–23 жовтня. Початок о 12:00 за київським часом. Доповідачі з Польщі, Литви та України представлять дослідження з комп'ютерного зору, обробки природної мови та інтелектуального аналізу даних. Трансляція в Microsoft Teams: https://teams.live.com/meet/943281737734, ID наради 943 281 737 734, секретний код HicAfX. Робочі мови конференції — українська та англійська.",
       "ev": [("Конференція «Інтелектуальні системи та технології»", [["інтелектуальні системи"]])]},
3061: {"t": "Підкажіть, будь ласка, чи правда, що консультацію перед іспитом з дискретної математики перенесли? Хтось у чаті потоку писав, що тепер вона буде не о 12:40 в ауд. 202, корпус 3, а десь онлайн, але офіційного оголошення я так і не побачив. Староста зараз на практиці й не відповідає. Якщо хтось точно знає, коли і де буде консультація, напишіть, бо не хочеться прийти в порожню аудиторію.",
       "ev": []},
3062: {"t": "24 листопада в ауд. 222, корпус 5 відбувся фінал факультетського конкурсу студентських стартапів. Захист проєктів тривав з 17:00 до пізнього вечора: журі переглянуло 11 презентацій і поставило чимало гострих запитань. Перше місце посів сервіс для обліку волонтерської допомоги, друге — застосунок для тренування жестової мови, третє — платформа для обміну підручниками. Дякуємо учасникам, менторам і журі! Переможці вже отримали сертифікати на навчання в бізнес-інкубаторі.",
       "ev": []},
3063: {"t": "Підбиваємо підсумки Дня кар'єри, який відбувся 29 вересня в ауд. 104, корпус 3. Уже з 12:00 біля стендів компаній вишикувалися черги, а загалом захід відвідали понад 200 студентів. Представники дев'яти ІТ-компаній провели 45 коротких співбесід, і щонайменше 12 наших студентів отримали запрошення на оплачувані стажування. Дякуємо Центру кар'єри за організацію та всім, хто прийшов! Фото вже в альбомі, а відгуки про захід можна залишити в анонімній формі.",
       "ev": []},
3064: {"t": "Увага, група КН-22! Змінено дату модульного іспиту з дисципліни «Теорія алгоритмів»: замість 11 листопада він відбудеться 13 листопада о 17:00 в аудиторії 104 (корпус №4). Причина — накладка з іспитом іншого потоку в тій самій аудиторії. Допуск до іспиту — за умови зарахування всіх лабораторних робіт до 9 листопада. Екзаменаційний білет складається з двох теоретичних питань і однієї задачі, тривалість — дві академічні години.",
       "ev": []},
3065: {"t": "Центр кар'єри університету організовує екскурсію до офісу ІТ-компанії, яка розробляє програмне забезпечення для логістики. Збір учасників — наступної п'ятниці об 11:30 в аудиторії 209 (корпус №2), звідти разом поїдемо до офісу. Ви побачите, як працюють команди розробників і тестувальників, поспілкуєтеся з тімлідами та дізнаєтеся про програму стажування компанії. Кількість місць — 15, записатися можна в Центрі кар'єри до кінця тижня. Поїздка безкоштовна.",
       "ev": [("Екскурсія до офісу ІТ-компанії", [["екскурс"]])]},
3066: {"t": "У п'ятницю, 20 листопада, в аудиторії 316 (корпус №4) відбудеться студентська конференція «Цифрові технології в освіті», початок о 10:00. Запрошуємо студентів 2 курсу виступити з короткими доповідями або просто прийти послухати колег. Теми доповідей: навчальні платформи, гейміфікація, адаптивне навчання, доступність освітніх сервісів для людей з інвалідністю. Тривалість виступу — до 7 хвилин, після кожного — 3 хвилини на запитання. Найкращі доповіді рекомендуємо до публікації у збірнику.",
       "ev": [("Студентська конференція «Цифрові технології в освіті»", [["цифрові технології"]])]},
3067: {"t": "Наукова бібліотека університету запрошує усіх охочих на вебінар «Scopus і Web of Science: як знайти журнал і перевірити свій профіль». Вебінар відбудеться 23 жовтня о 13:20 у Zoom: https://zoom.us/j/86038739798, ID 860 3873 9798, код доступу 532621. Покажемо, як шукати джерела за ключовими словами, оцінювати квартиль журналу, об'єднувати дублікати авторського профілю та налаштовувати сповіщення про нові цитування. Щоб отримати сертифікат учасника, заповніть реєстраційну анкету в бібліотеці до 21 жовтня.",
       "ev": [("Вебінар «Scopus і Web of Science»", [["scopus"]])]},
3068: {"t": "Сьогодні в залі засідань вченої ради науковий семінар кафедри програмної інженерії «Графові нейронні мережі», початок о 14:00. Доповідь зробить аспірантка Катерина Юрченко: вона покаже, як графові моделі передбачають властивості молекул і виявляють шахрайські транзакції в банківських мережах, та представить результати свого дисертаційного дослідження. Після доповіді — обговорення та запитання від рецензентів. Слайди будуть доступні на сторінці кафедри.",
       "ev": [("Науковий семінар «Графові нейронні мережі»", [["графов"]])]},
3069: {"t": "З Міжнародним днем студента, друзі! Студентські роки — це час експериментів, перших проєктів, безсонних ночей перед дедлайнами й дружби на все життя. Дякуємо, що ви робите наш факультет живим: пишете код, перемагаєте на олімпіадах, волонтерите й не боїтеся ставити незручні запитання. Окреме спасибі тим, хто вчора о 16:20 прийшов до аудиторії 217 (корпус №1) допомогти прикрасити її до свята. Бажаємо натхнення, легкої сесії та викладачів, які завжди на вашому боці!",
       "ev": []},
3070: {"t": "Запрошуємо студентів 2 курсу на зустріч із випускниками, яка відбудеться 2 грудня о 17:00 в амфітеатрі корпусу 4. Випускники різних років розкажуть, як знайшли першу роботу, які дисципліни виявилися найкориснішими і чого їм бракувало після університету. Ви зможете поставити запитання в неформальній атмосфері та, можливо, знайти наставника. Щоб ми підготували достатньо місць і кави, зареєструйтеся до 3 листопада: https://reg.example.ua/reg-2375.",
       "ev": [("Зустріч із випускниками", [["випускник"]])]},
3071: {"t": "Кафедра прикладної математики запрошує студентів 4 курсу на конференцію молодих вчених «Інформатика та кібернетика», яка триватиме 21–22 вересня. Щодня робота секцій розпочинатиметься о 9.30. У програмі — пленарні доповіді запрошених професорів, секції з математичного моделювання, штучного інтелекту та захисту інформації, а також постерна сесія для бакалаврів. Аудиторії для кожної секції повідомимо в програмі, яку надішлемо учасникам напередодні. Участь безкоштовна, тези приймаються до кінця цього тижня.",
       "ev": [("Конференція молодих вчених «Інформатика та кібернетика»", [["інформатика та кібернетика"]])]},
3072: {"t": "Друзі з наукового гуртка! Плануємо перше організаційне засідання в цьому семестрі, але не можемо визначитися з днем. Варіанти: у вівторок або у середу, початок об 11:30, аудиторія 416 (корпус №3). Голосуйте в опитуванні нижче до завтрашнього вечора, а якщо обидва дні не підходять, напишіть свій варіант у коментарях. Дату засідання оголосимо окремим постом, щойно підрахуємо голоси. На засіданні розподілимо теми досліджень і оберемо старосту гуртка.",
       "ev": []},
3073: {"t": "Затверджено нове положення про порядок ліквідації академічної заборгованості. Відтепер повторне складання дозволено не більше двох разів: перший — викладачу, другий — комісії з трьох осіб. Заяву на перескладання потрібно подати не пізніше ніж за 5 робочих днів, а положення набуває чинності з 10 жовтня. Паперові заяви приймає диспетчерська служба в аудиторії 316 (корпус №4) щодня з 10:20. Повний текст положення опубліковано на сайті університету в розділі «Нормативні документи».",
       "ev": []},
3074: {"t": "Кафедра кібербезпеки запрошує викладачів та студентів на практикум з Git для командної роботи. Заняття відбудеться 14 жовтня з 16:20 до 20:20 у комп'ютерному класі 317, корпус 2. За чотири години розберемо гілки, злиття і перебазування, розв'язання конфліктів, pull request'и та код-рев'ю, а наприкінці змоделюємо роботу команди з п'яти осіб над одним репозиторієм. Попередніх знань не потрібно, але бажано мати акаунт на GitHub. Буде перерва на каву.",
       "ev": [("Практикум з Git для командної роботи", [["git"]])]},
3075: {"t": "Завтра об 11:30 стартує онлайн-хакатон «GreenTech» для студентів старших курсів. Командам запропонують три кейси: оптимізація енергоспоживання гуртожитку, сервіс для сортування відходів і моніторинг якості води в річці. Відкриття та оголошення кейсів відбудеться в Google Meet: https://meet.google.com/dkj-ztpn-zrr, далі команди працюватимуть у своїх каналах і представлять рішення наступного дня. Призи — стажування в енергетичних компаніях та гранти на розвиток проєктів.",
       "ev": [("Онлайн-хакатон «GreenTech»", [["greentech"]])]},
}
